/**
 * Reading a file the user hands us.
 *
 * Four shapes are accepted, told apart by their own structure rather than
 * by file extension: the prototype's handwritten-notebook JSON (an array of
 * snake_case entries), a Lexpad export (an object with a `words` array), a
 * Kindle's My Clippings.txt, and a two-column CSV. The field mapping
 * mirrors the server's importer in
 * `apps/api/internal/app/transfer/format`, so a file imported here and the
 * same file imported there produce the same notebook.
 *
 * A Kindle's other file, vocab.db, is SQLite and is read by the server
 * instead; Settings sends that one on rather than parsing it here.
 */
import {
  normalizeHeadword,
  type LanguageCode,
  type Progress,
  type Source,
  type Word,
  LEVELS,
} from '@lexpad/core';
import type { ImportRow } from '@/db/mutations.js';
import type { StoredWord } from '@/db/schema.js';

/** One parsed entry, with the reference its own file used for relations. */
/** What the parsers produce; the import mutation numbers and dates them. */
export type ParsedRow = ImportRow;

export interface ParsedFile {
  rows: ParsedRow[];
  targetLang: LanguageCode | undefined;
  meaningLang: LanguageCode | undefined;
  /** Entries the file contained but that carried no headword. */
  skipped: number;
}

export class ImportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ImportError';
  }
}

type Meanings = NonNullable<Word['meanings']>;
type Phrases = NonNullable<Word['expressions']>;

/** Reads a file, choosing the parser from what is actually inside it. */
export function parseFile(name: string, text: string): ParsedFile {
  const trimmed = text.trim();
  if (trimmed === '') throw new ImportError('empty');
  if (trimmed.startsWith('[')) return parseLegacy(trimmed);
  if (trimmed.startsWith('{')) return parseLexpad(trimmed);
  // Before the CSV branch: a clippings file is full of commas and would
  // otherwise be read as one very wide spreadsheet.
  if (isClippings(trimmed)) return parseClippings(trimmed);
  if (name.toLowerCase().endsWith('.csv') || trimmed.includes(',') || trimmed.includes('\t')) {
    return parseCsv(trimmed);
  }
  throw new ImportError('unrecognised');
}

/* ---------------------------------------------------------------- legacy */

interface LegacyEntry {
  id?: number;
  page?: number;
  english?: string;
  farsi_original?: string;
  raw_note?: string;
  correction?: string | null;
  pos?: string;
  category?: string;
  level?: string;
  pronunciation?: string;
  tricky_spelling?: boolean;
  spelling_note?: string | null;
  meanings?: {
    meaning_fa?: string;
    meaning_en?: string;
    examples?: { en?: string; fa?: string }[];
  }[];
  expressions?: { en?: string; fa?: string }[];
  collocations?: string[];
  usage_note?: string;
  related_ids?: number[];
  related_note?: string;
  related_words?: { en?: string; fa?: string }[];
}

/** The prototype's notebook: an array of snake_case entries. */
export function parseLegacy(text: string): ParsedFile {
  const entries = asArray(text) as LegacyEntry[];
  const rows: ParsedRow[] = [];
  let skipped = 0;

  entries.forEach((entry, index) => {
    const headword = clean(entry.english);
    if (headword === '') {
      skipped += 1;
      return;
    }

    const meanings: Meanings = [];
    for (const meaning of entry.meanings ?? []) {
      const text_ = clean(meaning.meaning_fa);
      if (text_ === '') continue;
      const gloss = clean(meaning.meaning_en);
      meanings.push({
        meaning: text_,
        ...(gloss === '' ? {} : { gloss }),
        examples: (meaning.examples ?? []).flatMap((example) => {
          const sentence = clean(example.en);
          if (sentence === '') return [];
          const translation = clean(example.fa);
          return [{ sentence, ...(translation === '' ? {} : { translation }) }];
        }),
      });
    }
    // A page the reader could not transcribe still keeps its own words.
    const original = clean(entry.farsi_original);
    if (meanings.length === 0 && original !== '') meanings.push({ meaning: original, examples: [] });

    const usageNote = clean(entry.usage_note) || clean(entry.raw_note);
    const word: ParsedRow['word'] = {
      headword,
      category: clean(entry.category) || 'general',
      source: 'import',
      meanings,
      expressions: phrases(entry.expressions),
      collocations: (entry.collocations ?? []).map(clean).filter((value) => value !== ''),
      relatedWords: phrases(entry.related_words),
      relatedWordIds: [],
    };
    assign(word, 'pos', clean(entry.pos));
    assign(word, 'pronunciation', clean(entry.pronunciation));
    assign(word, 'spellingNote', clean(entry.spelling_note));
    assign(word, 'originalMeaning', original);
    assign(word, 'correction', clean(entry.correction));
    assign(word, 'usageNote', usageNote);
    assign(word, 'relatedNote', clean(entry.related_note));
    const level = asLevel(entry.level);
    if (level !== undefined) word.level = level;
    if (entry.tricky_spelling === true) word.trickySpelling = true;

    rows.push({
      ref: String(entry.id ?? index + 1),
      word,
      relatedRefs: (entry.related_ids ?? []).map(String),
    });
  });

  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: 'en', meaningLang: 'fa', skipped };
}

/* ------------------------------------------------------------- lexpad */

interface LexpadFile {
  words?: (Partial<StoredWord> & { id?: string; progress?: Progress })[];
  notebook?: { targetLang?: string; meaningLang?: string };
}

const SOURCES: readonly Source[] = ['manual', 'ai', 'assistant', 'import', 'shared'];

/** A file this app exported. Its words are already in the local shape. */
export function parseLexpad(text: string): ParsedFile {
  const parsed = asObject(text) as LexpadFile;
  if (!Array.isArray(parsed.words)) throw new ImportError('unrecognised');

  const rows: ParsedRow[] = [];
  let skipped = 0;
  parsed.words.forEach((entry, index) => {
    const headword = clean(entry.headword);
    if (headword === '') {
      skipped += 1;
      return;
    }
    // The learning state travels beside the word in the file, not on it.
    const { progress, ...content } = entry;
    const word: ParsedRow['word'] = {
      ...content,
      headword,
      category: clean(entry.category) || 'general',
      // A word this app wrote keeps where it came from; anything else is an import.
      source: entry.source !== undefined && SOURCES.includes(entry.source) ? entry.source : 'import',
      meanings: entry.meanings ?? [],
      expressions: entry.expressions ?? [],
      collocations: entry.collocations ?? [],
      relatedWords: entry.relatedWords ?? [],
      relatedWordIds: [],
    };
    const row: ParsedRow = {
      ref: entry.id ?? String(index + 1),
      word,
      relatedRefs: entry.relatedWordIds ?? [],
    };
    if (progress !== undefined && typeof progress.box === 'number') row.progress = progress;
    if (typeof entry.createdAt === 'string') row.createdAt = entry.createdAt;
    if (typeof entry.position === 'number') row.position = entry.position;
    rows.push(row);
  });

  if (rows.length === 0) throw new ImportError('no words');
  return {
    rows,
    targetLang: asLanguageOrUndefined(parsed.notebook?.targetLang),
    meaningLang: asLanguageOrUndefined(parsed.notebook?.meaningLang),
    skipped,
  };
}

/* --------------------------------------------------------------- kindle */

/**
 * The longest highlight that can become a headword.
 *
 * A Kindle highlight is usually a sentence or a whole paragraph, which
 * belongs in a reading app rather than in a vocabulary notebook; a word, a
 * phrasal verb or a short idiom is what Lexpad is for. Anything longer is
 * counted as skipped, so the import says what it left out.
 */
const MAX_CLIPPING_WORDS = 4;

/** Entries in My Clippings.txt are separated by a line of equals signs. */
const CLIPPING_SEPARATOR = '==========';

/** Whether this is a Kindle's My Clippings.txt rather than a spreadsheet. */
export function isClippings(text: string): boolean {
  return text.includes(CLIPPING_SEPARATOR) && /-\s*your\s+(highlight|note|bookmark)/i.test(text);
}

/**
 * My Clippings.txt: the book on the first line, what kind of clipping on
 * the second, and what was marked underneath.
 *
 * Only highlights become words. A bookmark holds no text, and a note is the
 * reader's own words about a highlight rather than something they met.
 */
export function parseClippings(text: string): ParsedFile {
  const rows: ParsedRow[] = [];
  let skipped = 0;
  const seen = new Set<string>();

  for (const entry of text.split(CLIPPING_SEPARATOR)) {
    const lines = entry
      .replace(/\r/g, '')
      .split('\n')
      .filter((line) => line.trim() !== '');
    if (lines.length < 3) continue;
    if (!/highlight/i.test(lines[1] ?? '')) continue;

    const marked = clean(lines.slice(2).join(' '));
    if (marked === '') continue;
    if (marked.split(/\s+/).length > MAX_CLIPPING_WORDS) {
      skipped += 1;
      continue;
    }
    const key = marked.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    rows.push({
      ref: key,
      word: {
        headword: marked,
        // The book the word was met in, so words read together stay
        // together instead of becoming one flat list.
        category: bookTitle(lines[0] ?? '') || 'general',
        source: 'import',
        // A Kindle knows the word and where it was read, never a meaning.
        meanings: [],
        expressions: [],
        collocations: [],
        relatedWords: [],
        relatedWordIds: [],
      },
      relatedRefs: [],
    });
  }

  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: undefined, meaningLang: undefined, skipped };
}

/** Drops the author from "Title (Author)", and anything absurdly long. */
function bookTitle(line: string): string {
  const title = clean(line).replace(/\s*\([^()]*\)$/, '');
  return title.length > 60 ? '' : title;
}

/* ------------------------------------------------------------------- csv */

/** Two columns: the word and its meaning. A header row is ignored. */
export function parseCsv(text: string): ParsedFile {
  const rows: ParsedRow[] = [];
  let skipped = 0;

  text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line !== '')
    .forEach((line, index) => {
      const cells = splitRow(line);
      const headword = clean(cells[0]);
      const meaning = clean(cells[1]);
      if (headword === '') {
        skipped += 1;
        return;
      }
      // A header row names its columns rather than holding a word.
      if (index === 0 && isHeader(headword, meaning)) return;
      rows.push({
        ref: String(index + 1),
        word: {
          headword,
          category: 'general',
          source: 'import',
          meanings: meaning === '' ? [] : [{ meaning, examples: [] }],
          expressions: [],
          collocations: [],
          relatedWords: [],
          relatedWordIds: [],
        },
        relatedRefs: [],
      });
    });

  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: undefined, meaningLang: undefined, skipped };
}

/** Splits one CSV or TSV row, honouring double quotes. */
function splitRow(line: string): string[] {
  if (line.includes('\t') && !line.includes(',')) return line.split('\t');
  const cells: string[] = [];
  let cell = '';
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index] ?? '';
    if (char === '"') {
      if (quoted && line[index + 1] === '"') {
        cell += '"';
        index += 1;
      } else {
        quoted = !quoted;
      }
      continue;
    }
    if (char === ',' && !quoted) {
      cells.push(cell);
      cell = '';
      continue;
    }
    cell += char;
  }
  cells.push(cell);
  return cells;
}

const HEADERS = new Set(['word', 'headword', 'term', 'front', 'english', 'meaning', 'back']);

function isHeader(first: string, second: string): boolean {
  return HEADERS.has(first.toLowerCase()) && (second === '' || HEADERS.has(second.toLowerCase()));
}

/* --------------------------------------------------------------- helpers */

/** Drops entries whose headword is already in the notebook. */
export function withoutDuplicates(rows: ParsedRow[], existing: readonly string[]): ParsedRow[] {
  const seen = new Set(existing.map(normalizeHeadword));
  return rows.filter((row) => {
    const key = normalizeHeadword(row.word.headword);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function asLevel(value: string | undefined): (typeof LEVELS)[number] | undefined {
  return LEVELS.find((level) => level === value?.toUpperCase());
}

const LANGS = ['en', 'de', 'tr', 'ar', 'fr', 'es', 'fa'] as const;

function asLanguageOrUndefined(value: string | undefined): LanguageCode | undefined {
  return LANGS.find((code) => code === value);
}

function phrases(input: { en?: string; fa?: string }[] | undefined): Phrases {
  return (input ?? []).flatMap((phrase) => {
    const text = clean(phrase.en);
    if (text === '') return [];
    const translation = clean(phrase.fa);
    return [{ text, ...(translation === '' ? {} : { translation }) }];
  });
}

/** The string-valued fields a parser may fill in. */
type TextField =
  'pos' | 'pronunciation' | 'spellingNote' | 'originalMeaning' | 'correction' | 'usageNote' | 'relatedNote';

/** Sets a field only when there is something to set, never to a blank. */
function assign(word: ParsedRow['word'], key: TextField, value: string): void {
  if (value !== '') word[key] = value;
}

function clean(value: string | null | undefined): string {
  return (value ?? '').replace(/\s+/g, ' ').trim();
}

function asArray(text: string): unknown[] {
  const parsed: unknown = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new ImportError('unrecognised');
  return parsed;
}

function asObject(text: string): object {
  const parsed: unknown = JSON.parse(text);
  if (typeof parsed !== 'object' || parsed === null) throw new ImportError('unrecognised');
  return parsed;
}
